package main
import("encoding/json";"fmt";"os";"path";"github.com/tickstep/aliyunpan/internal/config";"github.com/tickstep/aliyunpan/internal/command";"github.com/tickstep/aliyunpan-api/aliyunpan")
func fail(e interface{}){json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"error":fmt.Sprint(e)});os.Exit(1)}
func item(f *aliyunpan.FileEntity) map[string]interface{} {return map[string]interface{}{"id":f.FileId,"name":f.FileName,"path":f.Path,"isDir":f.IsFolder(),"size":f.FileSize,"modified":f.UpdatedAt,"hash":f.ContentHash,"hashType":f.ContentHashName}}
func main(){if len(os.Args)<3 {fail("usage: ali-bridge list|stat PATH [DRIVE]")};if e:=config.Config.Init();e!=nil{fail(e)};u:=config.Config.ActiveUser();if u==nil{fail("请先连接阿里云盘")};command.RefreshOpenTokenInNeed(u);drive:=u.ActiveDriveId;if len(os.Args)>3&&os.Args[3]!=""{drive=os.Args[3]};defer config.Config.Save();client:=u.PanClient().OpenapiPanClient();f,e:=client.FileInfoByPath(drive,os.Args[2]);if e!=nil{fail(e)};f.Path=os.Args[2];switch os.Args[1]{case "stat":json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"item":item(f)});case "list":if !f.IsFolder(){fail("不是目录")};files,e:=client.FileListGetAll(&aliyunpan.FileListParam{DriveId:drive,ParentFileId:f.FileId},200);if e!=nil{fail(e)};out:=[]map[string]interface{}{};for _,v:=range files{v.Path=path.Join(os.Args[2],v.FileName);out=append(out,item(v))};json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"items":out,"drives":u.DriveList,"drive":drive});default:fail("unsupported operation")}}
